insert into public.creative_skill_relationships (
  from_skill_id,
  from_skill_key,
  to_skill_id,
  to_skill_key,
  relationship_type,
  reason,
  strength,
  can_coexist,
  requires_storytiming_coordination,
  credit_relationship_notes,
  approval_relationship_notes,
  notes,
  lifecycle_status,
  metadata_json
)
select
  from_skill.id,
  seed.from_skill_key,
  to_skill.id,
  seed.to_skill_key,
  seed.relationship_type,
  seed.reason,
  seed.strength,
  seed.can_coexist,
  seed.requires_storytiming_coordination,
  seed.credit_relationship_notes,
  seed.approval_relationship_notes,
  seed.notes,
  seed.lifecycle_status,
  seed.metadata_json
from seed
join public.creative_skills from_skill
  on from_skill.skill_key = seed.from_skill_key
join public.creative_skills to_skill
  on to_skill.skill_key = seed.to_skill_key;

