insert into public.creative_skill_contract_mappings (
  skill_id,
  skill_key,
  planning_contract_type,
  required,
  mapping_role,
  required_before_credit_estimate,
  required_before_approval,
  required_before_future_execution,
  attachment_reason,
  expected_plan_record_type,
  status,
  version,
  metadata_json
)
select
  skill.id,
  seed.skill_key,
  seed.planning_contract_type,
  seed.required,
  seed.mapping_role,
  seed.required_before_credit_estimate,
  seed.required_before_approval,
  seed.required_before_future_execution,
  seed.attachment_reason,
  seed.expected_plan_record_type,
  seed.status,
  seed.version,
  seed.metadata_json
from seed
join public.creative_skills skill
  on skill.skill_key = seed.skill_key;

do $$
begin
  if (select count(*) from public.creative_skill_families) <> 21 then
    raise exception 'RP-SKILLS-31 expected 21 creative_skill_families rows';
  end if;

  if (select count(*) from public.creative_skills) <> 140 then
    raise exception 'RP-SKILLS-31 expected 140 creative_skills rows';
  end if;

  if (select count(*) from public.creative_skill_aliases) <> 9 then
    raise exception 'RP-SKILLS-31 expected 9 creative_skill_aliases rows';
  end if;

  if (select count(*) from public.creative_skill_relationships) <> 20 then
    raise exception 'RP-SKILLS-31 expected 20 creative_skill_relationships rows';
  end if;

  if (select count(*) from public.creative_skill_contract_mappings) <> 450 then
    raise exception 'RP-SKILLS-31 expected 450 creative_skill_contract_mappings rows';
  end if;

  if (select count(*) from public.creative_skill_duplicate_reviews) <> 0 then
    raise exception 'RP-SKILLS-31 expected 0 creative_skill_duplicate_reviews rows';
  end if;

  if exists (
    select 1
    from public.creative_skills skill
    left join public.creative_skill_families family
      on family.id = skill.family_id
    where family.id is null
  ) then
    raise exception 'RP-SKILLS-31 found creative_skills rows without valid families';
  end if;

  if exists (
    select 1
    from public.creative_skill_aliases alias
    left join public.creative_skills skill
      on skill.id = alias.canonical_skill_id
    where skill.id is null
  ) then
    raise exception 'RP-SKILLS-31 found aliases without valid canonical skills';
  end if;

  if exists (
    select 1
    from public.creative_skill_relationships relationship
    left join public.creative_skills from_skill
      on from_skill.id = relationship.from_skill_id
    left join public.creative_skills to_skill
      on to_skill.id = relationship.to_skill_id
    where from_skill.id is null
      or to_skill.id is null
  ) then
    raise exception 'RP-SKILLS-31 found relationships without valid endpoints';
  end if;

  if exists (
    select 1
    from public.creative_skill_relationships
    where from_skill_id = to_skill_id
      or from_skill_key = to_skill_key
  ) then
    raise exception 'RP-SKILLS-31 found self-referential relationships';
  end if;

  if exists (
    select 1
    from public.creative_skills skill
    where not exists (
      select 1
      from public.creative_skill_contract_mappings mapping
      where mapping.skill_id = skill.id
        and mapping.planning_contract_type = 'universal_skill_plan'
    )
  ) then
    raise exception 'RP-SKILLS-31 found skills missing universal_skill_plan mapping';
  end if;

  if exists (
    select 1
    from public.creative_skills skill
    where (
      select count(*)
      from public.creative_skill_contract_mappings mapping
      where mapping.skill_id = skill.id
        and mapping.mapping_role = 'primary'
    ) <> 1
  ) then
    raise exception 'RP-SKILLS-31 found skills without exactly one primary contract mapping';
  end if;

  if exists (
    select skill_id, planning_contract_type
    from public.creative_skill_contract_mappings
    group by skill_id, planning_contract_type
    having count(*) > 1
  ) then
    raise exception 'RP-SKILLS-31 found duplicate skill/contract mappings';
  end if;

  if (
    select count(*)
    from public.creative_skills
    where skill_key in ('no_captions', 'no_transition', 'no_b_roll', 'no_overlay', 'no_graphic_design', 'no_motion_design', 'no_3d', 'no_stroke_motion', 'no_real_motion', 'no_browser_app_visual', 'no_music', 'no_sfx')
      and no_action_counterpart_skill_id is not null
  ) <> 12 then
    raise exception 'RP-SKILLS-31 expected 12 resolved no-action counterparts';
  end if;

  if exists (
    select 1
    from public.creative_skills
    where no_action_counterpart_skill_id = id
  ) then
    raise exception 'RP-SKILLS-31 found self-referential no-action counterpart';
  end if;

  if exists (
    select family_key
    from public.creative_skill_families
    group by family_key
    having count(*) > 1
  ) then
    raise exception 'RP-SKILLS-31 found duplicate family keys';
  end if;

  if exists (
    select skill_key
    from public.creative_skills
    group by skill_key
    having count(*) > 1
  ) then
    raise exception 'RP-SKILLS-31 found duplicate skill keys';
  end if;
end $$;
